use std::{collections::BTreeSet,fs,path::Path};
use regex::Regex;use roxmltree::Document;use walkdir::WalkDir;
use crate::model::{DoxygenSymbol,LegacyTest,LegacyTestKind,RustTest,VerificationClass};
pub fn discover_legacy_tests(root:&Path)->Result<Vec<LegacyTest>,Box<dyn std::error::Error>>{let mut out=BTreeSet::new();for(e,kind)in[(root.join("trinityal/tests"),0),(root.join("trinity/tests/Python/tests"),1)]{if !e.exists(){continue}for ent in WalkDir::new(e).into_iter().filter_map(Result::ok){if !ent.file_type().is_file(){continue}let ext=ent.path().extension().and_then(|x|x.to_str());if(kind==0&&!matches!(ext,Some("cpp"|"cc"|"cxx")))||(kind==1&&ext!=Some("py")){continue}let src=relative(root,ent.path());let text=fs::read_to_string(ent.path())?;if kind==0{out.extend(discover_gtest_text(&src,&text))}else{out.extend(discover_python_text(&src,&text))}}}Ok(out.into_iter().collect())}
#[must_use]pub fn discover_gtest_text(source:&str,text:&str)->Vec<LegacyTest>{let re=Regex::new(r"\bTEST(?:_F|_P)?\s*\(\s*([^,]+)\s*,\s*([^)]+)\)").unwrap();let mut out=BTreeSet::new();for c in re.captures_iter(text){let suite=c[1].trim().to_owned();let name=c[2].trim().to_owned();let pos=c.get(0).map_or(0,|m|m.start());let line=u32::try_from(text[..pos].bytes().filter(|b|*b==b'\n').count()+1).ok();let id=format!("{source}::{suite}::{name}");let lower=id.to_ascii_lowercase();let v=if source.ends_with("ALResultTest.cpp")||source.ends_with("BitmapDimensions.cpp")||source.ends_with("VertexDefinition.cpp")||source.ends_with("TextureSubresource.cpp"){VerificationClass::Kani}else if lower.contains("screenshot"){VerificationClass::Screenshot}else if ["render","swapchain","raytracing","compute","gpu","occlusion","fence","texture","buffer","shader"].iter().any(|n|lower.contains(n)){VerificationClass::RenderDevice}else{VerificationClass::Integration};out.insert(LegacyTest{id,source:source.into(),suite,name,line,kind:LegacyTestKind::CppGTest,suggested_verification:v});}out.into_iter().collect()}
#[must_use]pub fn discover_python_text(source:&str,text:&str)->Vec<LegacyTest>{let mut out=BTreeSet::new();let mut class="module".to_owned();for(i,line)in text.lines().enumerate(){let t=line.trim();if let Some(r)=t.strip_prefix("class "){class=r.split(['(',':']).next().unwrap_or("module").trim().to_owned();continue}if let Some(r)=t.strip_prefix("def "){let name=r.split('(').next().unwrap_or("").trim();if name.starts_with("test_"){out.insert(LegacyTest{id:format!("{source}::{class}::{name}"),source:source.into(),suite:class.clone(),name:name.into(),line:u32::try_from(i+1).ok(),kind:LegacyTestKind::Python,suggested_verification:VerificationClass::Kani});}}}out.into_iter().collect()}
pub fn discover_rust_tests(root:&Path)->Result<Vec<RustTest>,Box<dyn std::error::Error>>{let mut out=BTreeSet::new();for ent in WalkDir::new(root.join("crates")).into_iter().filter_map(Result::ok){if !ent.file_type().is_file()||ent.path().extension().and_then(|x|x.to_str())!=Some("rs"){continue}let rel=relative(root,ent.path());if !rel.contains("/tests/")||rel.ends_with("_kani_generated.rs"){continue}let crate_name=rel.split('/').nth(1).unwrap_or("unknown").to_owned();let text=fs::read_to_string(ent.path())?;let file=syn::parse_file(&text)?;for item in file.items{let syn::Item::Fn(f)=item else{continue};let Some(a)=f.attrs.iter().find(|a|a.path().is_ident("trinity_test"))else{continue};let mut legacy=String::new();let mut verification=VerificationClass::Kani;a.parse_nested_meta(|m|{if m.path.is_ident("legacy"){legacy=m.value()?.parse::<syn::LitStr>()?.value()}else if m.path.is_ident("verification"){verification=match m.value()?.parse::<syn::LitStr>()?.value().as_str(){"kani"=>VerificationClass::Kani,"native"=>VerificationClass::Native,"render-device"=>VerificationClass::RenderDevice,"screenshot"=>VerificationClass::Screenshot,"integration"=>VerificationClass::Integration,_=>VerificationClass::Unmapped}}Ok(())})?;let function=f.sig.ident.to_string();let source=rel.strip_prefix(&format!("crates/{crate_name}/tests/")).unwrap_or(&rel).to_owned();out.insert(RustTest{crate_name:crate_name.clone(),source,function:function.clone(),body_name:format!("__trinity_test_body_{function}"),legacy,verification});}}Ok(out.into_iter().collect())}
pub fn discover_doxygen_symbols(xml:&Path)->Result<Vec<DoxygenSymbol>,Box<dyn std::error::Error>>{let mut out=BTreeSet::new();if !xml.exists(){return Ok(vec![])}for ent in WalkDir::new(xml).into_iter().filter_map(Result::ok){if !ent.file_type().is_file()||ent.path().extension().and_then(|x|x.to_str())!=Some("xml"){continue}let text=fs::read_to_string(ent.path())?;let Ok(doc)=Document::parse(&text)else{continue};for c in doc.descendants().filter(|n|n.has_tag_name("compounddef")){let name=child(c,"compoundname").unwrap_or_default();let src=c.descendants().find(|n|n.has_tag_name("location")).and_then(|n|n.attribute("file")).unwrap_or("").replace('\\',"/");if !name.is_empty(){out.insert(DoxygenSymbol{source:src.clone(),qualified_name:name.clone(),kind:c.attribute("kind").unwrap_or("compound").into()});}for m in c.descendants().filter(|n|n.has_tag_name("memberdef")){if let Some(n)=child(m,"name"){out.insert(DoxygenSymbol{source:src.clone(),qualified_name:if name.is_empty(){n}else{format!("{name}::{n}")},kind:m.attribute("kind").unwrap_or("member").into()});}}}}Ok(out.into_iter().collect())}
fn child(n:roxmltree::Node<'_,'_>,tag:&str)->Option<String>{n.children().find(|c|c.has_tag_name(tag)).and_then(|c|c.text()).map(str::trim).filter(|s|!s.is_empty()).map(ToOwned::to_owned)}fn relative(root:&Path,path:&Path)->String{path.strip_prefix(root).unwrap_or(path).to_string_lossy().replace('\\',"/")}
